"use strict";(self.webpackChunkpimcore_documentation=self.webpackChunkpimcore_documentation||[]).push([[487444],{291532:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>p,frontMatter:()=>s,metadata:()=>r,toc:()=>c});var i=t(474848),o=t(28453);const s={},a="Apache Configuration",r={id:"Pimcore/Installation_and_Upgrade/System_Setup_and_Hosting/Apache_Configuration",title:"Apache Configuration",description:".htaccess",source:"@site/versioned_docs/version-2024.3/0002_Pimcore/23_Installation_and_Upgrade/03_System_Setup_and_Hosting/01_Apache_Configuration.md",sourceDirName:"0002_Pimcore/23_Installation_and_Upgrade/03_System_Setup_and_Hosting",slug:"/Pimcore/Installation_and_Upgrade/System_Setup_and_Hosting/Apache_Configuration",permalink:"/2024.3/Pimcore/Installation_and_Upgrade/System_Setup_and_Hosting/Apache_Configuration",draft:!1,unlisted:!1,editUrl:"https://github.com/pimcore/pimcore/edit/11.x/doc/23_Installation_and_Upgrade/03_System_Setup_and_Hosting/01_Apache_Configuration.md",tags:[],version:"2024.3",sidebarPosition:1,frontMatter:{},sidebar:"myAutogeneratedSidebar",previous:{title:"System Setup & Hosting/Infrastructure Topics",permalink:"/2024.3/Pimcore/Installation_and_Upgrade/System_Setup_and_Hosting/"},next:{title:"Nginx Configuration",permalink:"/2024.3/Pimcore/Installation_and_Upgrade/System_Setup_and_Hosting/Nginx_Configuration"}},l={},c=[{value:".htaccess",id:"htaccess",level:2},{value:"Virtual Hosts",id:"virtual-hosts",level:2},{value:"Example",id:"example",level:4}];function d(e){const n={code:"code",h1:"h1",h2:"h2",h4:"h4",header:"header",p:"p",pre:"pre",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"apache-configuration",children:"Apache Configuration"})}),"\n",(0,i.jsx)(n.h2,{id:"htaccess",children:".htaccess"}),"\n",(0,i.jsxs)(n.p,{children:["All the necessary rewrite rules, which are needed for Pimcore to work, must be defined in the ",(0,i.jsx)(n.code,{children:".htaccess"})," file on path ",(0,i.jsx)(n.code,{children:"public/.htaccess"}),",\nas below:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-apacheconf",children:'# Use the front controller as index file. It serves as a fallback solution when\n# every other rewrite/redirect fails (e.g. in an aliased environment without\n# mod_rewrite). Additionally, this reduces the matching process for the\n# start page (path "/") because otherwise Apache will apply the rewriting rules\n# to each configured DirectoryIndex file (e.g. index.php, index.html, index.pl).\nDirectoryIndex index.php\n\n# By default, Apache does not evaluate symbolic links if you did not enable this\n# feature in your server configuration. Uncomment the following line if you\n# install assets as symlinks or if you experience problems related to symlinks\n# when compiling LESS/Sass/CoffeScript assets.\n# Options FollowSymlinks\n\n# Disabling MultiViews prevents unwanted negotiation, e.g. "/index" should not resolve\n# to the front controller "/index.php" but be rewritten to "/index.php/index".\n<IfModule mod_negotiation.c>\n    Options -MultiViews\n</IfModule>\n\n# mime types\nAddType video/mp4 .mp4\nAddType video/webm .webm\nAddType image/webp .webp\nAddType image/jpeg .pjpeg\n\nOptions +SymLinksIfOwnerMatch\n\n# Use UTF-8 encoding for anything served text/plain or text/html\nAddDefaultCharset utf-8\n\nRewriteEngine On\n\n<IfModule mod_headers.c>\n    <FilesMatch "\\.(jpe?g|png)$">\n        Header always unset X-Content-Type-Options\n    </FilesMatch>\n</IfModule>\n\n# Determine the RewriteBase automatically and set it as environment variable.\n# If you are using Apache aliases to do mass virtual hosting or installed the\n# project in a subdirectory, the base path will be prepended to allow proper\n# resolution of the index.php file and to redirect to the correct URI. It will\n# work in environments without path prefix as well, providing a safe, one-size\n# fits all solution. But as you do not need it in this case, you can comment\n# the following 2 lines to eliminate the overhead.\nRewriteCond %{REQUEST_URI}::$1 ^(/.+)/(.*)::\\2$\nRewriteRule ^(.*) - [E=BASE:%1]\n\n# Sets the HTTP_AUTHORIZATION header removed by Apache\nRewriteCond %{HTTP:Authorization} .\nRewriteRule ^ - [E=HTTP_AUTHORIZATION:%{HTTP:Authorization}]\n\n# Redirect to URI without front controller to prevent duplicate content\n# (with and without `/index.php`). Only do this redirect on the initial\n# rewrite by Apache and not on subsequent cycles. Otherwise we would get an\n# endless redirect loop (request -> rewrite to front controller ->\n# redirect -> request -> ...).\n# So in case you get a "too many redirects" error or you always get redirected\n# to the start page because your Apache does not expose the REDIRECT_STATUS\n# environment variable, you have 2 choices:\n# - disable this feature by commenting the following 2 lines or\n# - use Apache >= 2.3.9 and replace all L flags by END flags and remove the\n#   following RewriteCond (best solution)\nRewriteCond %{ENV:REDIRECT_STATUS} ^$\nRewriteRule ^index\\.php(?:/(.*)|$) %{ENV:BASE}/$1 [R=301,L]\n\n<IfModule mod_status.c>\n    RewriteCond %{REQUEST_URI} ^/(fpm|server)-(info|status|ping)\n    RewriteRule . - [L]\n</IfModule>\n\n# restrict access to dotfiles\nRewriteCond %{REQUEST_FILENAME} -d [OR]\nRewriteCond %{REQUEST_FILENAME} -l [OR]\nRewriteCond %{REQUEST_FILENAME} -f\nRewriteRule /\\.|^\\.(?!well-known/) - [F,L]\n\n# ASSETS: check if request method is GET (because of WebDAV) and if the requested file (asset) exists on the filesystem, if both match, deliver the asset directly\nRewriteCond %{REQUEST_METHOD} ^(GET|HEAD)\nRewriteCond %{DOCUMENT_ROOT}/var/assets%{REQUEST_URI} -f\nRewriteRule ^(.*)$ /var/assets%{REQUEST_URI} [PT,L]\n\n# Thumbnails\nRewriteCond %{REQUEST_URI} .*/(image|video)-thumb__[\\d]+__.*\nRewriteCond %{DOCUMENT_ROOT}/var/tmp/thumbnails%{REQUEST_URI} -f\nRewriteRule ^(.*)$ /var/tmp/thumbnails%{REQUEST_URI} [PT,L]\n\n# static pages\nSetEnvIf Request_URI ^(.*)$ STATIC_PAGE_URI=$1\nSetEnvIf Request_URI / STATIC_PAGE_URI=/%home\n\nRewriteCond %{REQUEST_METHOD} ^(GET|HEAD)\nRewriteCond %{QUERY_STRING}   !(pimcore_editmode=true|pimcore_preview|pimcore_version)\nRewriteCond %{DOCUMENT_ROOT}/var/tmp/pages%{STATIC_PAGE_URI}.html -f\nRewriteRule ^(.*)$ /var/tmp/pages%{STATIC_PAGE_URI}.html [PT,L]\n\n# cache-buster rule for scripts & stylesheets embedded using view helpers\nRewriteRule ^cache-buster\\-[\\d]+/(.*) $1 [PT,L]\n\n# If the requested filename exists, simply serve it.\n# We only want to let Apache serve files and not directories.\nRewriteCond %{REQUEST_FILENAME} -f\nRewriteRule ^ - [L]\n\n# Rewrite all other queries to the front controller.\nRewriteRule ^ %{ENV:BASE}/index.php [L]\n\n\n\n\n##########################################\n### OPTIONAL PERFORMANCE OPTIMIZATIONS ###\n##########################################\n\n<IfModule mod_deflate.c>\n    # Force compression for mangled headers.\n    # http://developer.yahoo.com/blogs/ydn/posts/2010/12/pushing-beyond-gzipping\n    <IfModule mod_setenvif.c>\n        <IfModule mod_headers.c>\n            SetEnvIfNoCase ^(Accept-EncodXng|X-cept-Encoding|X{15}|~{15}|-{15})$ ^((gzip|deflate)\\s*,?\\s*)+|[X~-]{4,13}$ HAVE_Accept-Encoding\n            RequestHeader append Accept-Encoding "gzip,deflate" env=HAVE_Accept-Encoding\n        </IfModule>\n    </IfModule>\n\n    # Compress all output labeled with one of the following MIME-types\n    # (for Apache versions below 2.3.7, you don\'t need to enable `mod_filter`\n    #  and can remove the `<IfModule mod_filter.c>` and `</IfModule>` lines\n    #  as `AddOutputFilterByType` is still in the core directives).\n    <IfModule mod_filter.c>\n        AddOutputFilterByType DEFLATE application/atom+xml application/javascript application/json \\\n            application/vnd.ms-fontobject application/x-font-ttf application/rss+xml \\\n            application/x-web-app-manifest+json application/xhtml+xml \\\n            application/xml font/opentype image/svg+xml image/x-icon \\\n            text/css text/html text/plain text/x-component text/xml text/javascript\n    </IfModule>\n</IfModule>\n\n<IfModule mod_expires.c>\n    ExpiresActive on\n    ExpiresDefault "access plus 31536000 seconds"\n\n    # specific overrides\n    #ExpiresByType text/css "access plus 1 year"\n</IfModule>\n\n<IfModule pagespeed_module>\n    # pimcore mod_pagespeed integration\n    # pimcore automatically disables mod_pagespeed in the following situations: debug-mode on, /admin, preview, editmode, ...\n    # if you want to disable pagespeed for specific actions in pimcore you can use $this->disableBrowserCache() in your action\n    RewriteCond %{REQUEST_URI} ^/(mod_)?pagespeed_(statistics|message|console|beacon|admin|global_admin)\n    RewriteRule . - [L]\n\n    ModPagespeed Off\n    AddOutputFilterByType MOD_PAGESPEED_OUTPUT_FILTER text/html\n    ModPagespeedModifyCachingHeaders off\n    ModPagespeedRewriteLevel PassThrough\n    # low risk filters\n    ModPagespeedEnableFilters remove_comments,recompress_images\n    # low and moderate filters, recommended filters, but can cause problems\n    ModPagespeedEnableFilters lazyload_images,extend_cache_images,inline_preview_images,sprite_images\n    ModPagespeedEnableFilters combine_css,rewrite_css,move_css_to_head,flatten_css_imports,extend_cache_css,prioritize_critical_css\n    ModPagespeedEnableFilters extend_cache_scripts,combine_javascript,canonicalize_javascript_libraries,rewrite_javascript\n    # high risk\n    #ModPagespeedEnableFilters defer_javascript,local_storage_cache\n</IfModule>\n'})}),"\n",(0,i.jsx)(n.h2,{id:"virtual-hosts",children:"Virtual Hosts"}),"\n",(0,i.jsxs)(n.p,{children:["Make sure ",(0,i.jsx)(n.code,{children:"Allowoverride All"})," is set for the ",(0,i.jsx)(n.code,{children:"DocumentRoot"}),", which enables ",(0,i.jsx)(n.code,{children:".htaccess"})," support."]}),"\n",(0,i.jsx)(n.h4,{id:"example",children:"Example"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-apacheconf",children:'<VirtualHost *:443>\n        ServerName YOUPROJECT.local\n        DocumentRoot  /var/www/public\n\n        <FilesMatch \\.php$>\n            SetHandler "proxy:unix:/var/run/php/pimcore.sock|fcgi://localhost"\n        </FilesMatch>\n\n        <Directory /var/www/public>\n                Options FollowSymLinks\n                AllowOverride All\n                Require all granted\n        </Directory>\n\n        SSLEngine on\n        # NEEDS TO BE CHANGED\n        SSLCertificateFile /etc/getssl/YOUPROJECT.local/YOUPROJECT.local.crt\n        SSLCertificateKeyFile /etc/getssl/YOUPROJECT.local/YOUPROJECT.local.key\n        SSLCertificateChainFile /etc/getssl/YOUPROJECT.local/chain.crt\n\n        RewriteEngine On\n\n        # THE FOLLOWING NEEDS TO BE THE VERY LAST REWRITE RULE IN THIS VHOST\n        # this is needed to pass the auth header correctly - fastcgi environment\n        RewriteRule ".*" "-" [E=HTTP_AUTHORIZATION:%{HTTP:Authorization},L]\n\n        ErrorLog ${APACHE_LOG_DIR}/YOUPROJECT.local_443_error.log\n        CustomLog ${APACHE_LOG_DIR}/YOUPROJECT.local_443_access.log combined\n</VirtualHost>\n'})})]})}function p(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453:(e,n,t)=>{t.d(n,{R:()=>a,x:()=>r});var i=t(296540);const o={},s=i.createContext(o);function a(e){const n=i.useContext(s);return i.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);